 "honshiken_school_koko_top_rika_12": {
  "caption": "答え　(1) 約67％　(2) 約118g",
  "slides": [
   {
    "note": "露点から湿度を求め、湿度を 80％にするために必要な水蒸気の量を求める。",
    "add": [
     {
      "t": "box",
      "x": 0,
      "y": 0,
      "w": 320,
      "h": 240,
      "color": "#FFFFFF",
      "fill": "#FFFFFF"
     },
     {
      "t": "label",
      "x": 12,
      "y": 16,
      "text": "【何を聞かれているか】",
      "size": 11,
      "color": "#6E645C",
      "anchor": "start",
      "bold": true
     },
     {
      "t": "box",
      "x": 12,
      "y": 26,
      "w": 296,
      "h": 26,
      "text": "室温 24℃　露点 17℃　部屋 40m³",
      "color": "#6E645C",
      "fill": "#F1EFEA",
      "size": 13
     },
     {
      "t": "box",
      "x": 12,
      "y": 58,
      "w": 296,
      "h": 26,
      "text": "(1) 湿度　(2) 加える水蒸気",
      "color": "#6E645C",
      "fill": "#F1EFEA",
      "size": 13
     }
    ]
   },
   {
    "note": "空気を冷やしていくと、ある温度で水蒸気がちょうど飽和して水滴になる。この温度が露点。露点での飽和水蒸気量は、いまの空気 1m³ にふくまれる水蒸気量に等しい。湿度は、いまの水蒸気量÷その温度での飽和水蒸気量×100。",
    "add": [
     {
      "t": "box",
      "x": 0,
      "y": 0,
      "w": 320,
      "h": 240,
      "color": "#FFFFFF",
      "fill": "#FFFFFF"
     },
     {
      "t": "label",
      "x": 12,
      "y": 16,
      "text": "【なぜそうなるのか】",
      "size": 11,
      "color": "#9333EA",
      "anchor": "start",
      "bold": true
     },
     {
      "t": "box",
      "x": 12,
      "y": 26,
      "w": 296,
      "h": 26,
      "text": "露点の飽和水蒸気量＝いまの水蒸気量",
      "color": "#9333EA",
      "fill": "#F3E8FF",
      "size": 13
     },
     {
      "t": "box",
      "x": 12,
      "y": 58,
      "w": 296,
      "h": 26,
      "text": "湿度＝水蒸気量÷飽和水蒸気量×100",
      "color": "#9333EA",
      "fill": "#F3E8FF",
      "size": 13
     }
    ]
   },
   {
    "note": "(1) 空気 1m³ の水蒸気量は 17℃の飽和水蒸気量 14.5g。24℃の飽和水蒸気量は 21.8g。湿度＝14.5÷21.8×100＝66.5…％。約67％。",
    "add": [
     {
      "t": "box",
      "x": 0,
      "y": 0,
      "w": 320,
      "h": 240,
      "color": "#FFFFFF",
      "fill": "#FFFFFF"
     },
     {
      "t": "label",
      "x": 12,
      "y": 16,
      "text": "【ステップ1】",
      "size": 11,
      "color": "#0284C7",
      "anchor": "start",
      "bold": true
     },
     {
      "t": "box",
      "x": 12,
      "y": 26,
      "w": 296,
      "h": 26,
      "text": "(1) 14.5÷21.8×100＝66.5…",
      "color": "#0284C7",
      "fill": "#E0F2FE",
      "size": 13
     },
     {
      "t": "box",
      "x": 12,
      "y": 58,
      "w": 296,
      "h": 26,
      "text": "約67％",
      "color": "#0284C7",
      "fill": "#E0F2FE",
      "size": 13
     }
    ]
   },
   {
    "note": "(2) 湿度 80％のとき、1m³ にふくまれる水蒸気量は 21.8×0.8＝17.44g。",
    "add": [
     {
      "t": "box",
      "x": 0,
      "y": 0,
      "w": 320,
      "h": 240,
      "color": "#FFFFFF",
      "fill": "#FFFFFF"
     },
     {
      "t": "label",
      "x": 12,
      "y": 16,
      "text": "【ステップ2】",
      "size": 11,
      "color": "#0284C7",
      "anchor": "start",
      "bold": true
     },
     {
      "t": "box",
      "x": 12,
      "y": 26,
      "w": 296,
      "h": 26,
      "text": "21.8×0.8＝17.44g/m³",
      "color": "#0284C7",
      "fill": "#E0F2FE",
      "size": 13
     }
    ]
   },
   {
    "note": "いまは 14.5g/m³ なので、1m³ あたり 17.44−14.5＝2.94g 足りない。部屋は 40m³ なので 2.94×40＝117.6g。約118g。",
    "add": [
     {
      "t": "box",
      "x": 0,
      "y": 0,
      "w": 320,
      "h": 240,
      "color": "#FFFFFF",
      "fill": "#FFFFFF"
     },
     {
      "t": "label",
      "x": 12,
      "y": 16,
      "text": "【ステップ3】",
      "size": 11,
      "color": "#0284C7",
      "anchor": "start",
      "bold": true
     },
     {
      "t": "box",
      "x": 12,
      "y": 26,
      "w": 296,
      "h": 26,
      "text": "不足 17.44−14.5＝2.94g/m³",
      "color": "#0284C7",
      "fill": "#E0F2FE",
      "size": 13
     },
     {
      "t": "box",
      "x": 12,
      "y": 58,
      "w": 296,
      "h": 26,
      "text": "2.94×40＝117.6g　約118g",
      "color": "#0284C7",
      "fill": "#E0F2FE",
      "size": 13
     }
    ]
   },
   {
    "note": "(1) 約67％　(2) 約118g。",
    "add": [
     {
      "t": "box",
      "x": 0,
      "y": 0,
      "w": 320,
      "h": 240,
      "color": "#FFFFFF",
      "fill": "#FFFFFF"
     },
     {
      "t": "label",
      "x": 12,
      "y": 16,
      "text": "【答え】",
      "size": 11,
      "color": "#16A34A",
      "anchor": "start",
      "bold": true
     },
     {
      "t": "box",
      "x": 12,
      "y": 26,
      "w": 296,
      "h": 26,
      "text": "(1) 約67％　(2) 約118g",
      "color": "#16A34A",
      "fill": "#DCFCE7",
      "size": 13
     }
    ]
   },
   {
    "note": "(2) の確かめ。加える前の水蒸気は 14.5×40＝580g。加えたあとは 580＋117.6＝697.6g。これを 40m³ で割ると 17.44g/m³。24℃の飽和水蒸気量 21.8g/m³ との比は 17.44÷21.8＝0.8 で、80％になる。",
    "add": [
     {
      "t": "box",
      "x": 0,
      "y": 0,
      "w": 320,
      "h": 240,
      "color": "#FFFFFF",
      "fill": "#FFFFFF"
     },
     {
      "t": "label",
      "x": 12,
      "y": 16,
      "text": "【確かめ】",
      "size": 11,
      "color": "#B5622E",
      "anchor": "start",
      "bold": true
     },
     {
      "t": "box",
      "x": 12,
      "y": 26,
      "w": 296,
      "h": 26,
      "text": "580＋117.6＝697.6g",
      "color": "#B5622E",
      "fill": "#FEF9C3",
      "size": 13
     },
     {
      "t": "box",
      "x": 12,
      "y": 58,
      "w": 296,
      "h": 26,
      "text": "697.6÷40÷21.8＝0.8",
      "color": "#B5622E",
      "fill": "#FEF9C3",
      "size": 13
     }
    ]
   },
   {
    "note": "(1) で、17℃と 24℃の差（7）を使って湿度を出そうとする誤り。湿度は、水蒸気量の「比」で出す。(2) で、1m³ あたりの 2.94g を答えとし、40 倍するのを忘れる誤りも多い。",
    "add": [
     {
      "t": "box",
      "x": 0,
      "y": 0,
      "w": 320,
      "h": 240,
      "color": "#FFFFFF",
      "fill": "#FFFFFF"
     },
     {
      "t": "label",
      "x": 12,
      "y": 16,
      "text": "【よくあるまちがい】",
      "size": 11,
      "color": "#E11D48",
      "anchor": "start",
      "bold": true
     },
     {
      "t": "box",
      "x": 12,
      "y": 26,
      "w": 296,
      "h": 26,
      "text": "温度差ではなく、水蒸気量の比",
      "color": "#E11D48",
      "fill": "#FFE4E6",
      "size": 13
     },
     {
      "t": "box",
      "x": 12,
      "y": 58,
      "w": 296,
      "h": 26,
      "text": "部屋の広さ（40m³）をかける",
      "color": "#E11D48",
      "fill": "#FFE4E6",
      "size": 13
     }
    ]
   }
  ]
 },
